      for (x = 0; x < w; x += 22) o += '<rect class="fence" x="' + x + '" y="' + (h - 40) + '" width="5" height="18"/>'; o += '<rect class="fence" x="0" y="' + (h - 34) + '" width="' + w + '" height="3"/>';
